SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, AVG(p.dod - p.admittime) AS average_length_of_stay FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND p.anchor_year = 71 AND p.anchor_year_group = 'AMI' AND p.dod IS NOT NULL AND a.admission_type = 'emergency' GROUP BY a.los, a.is_emergency ORDER BY a.los, a.is_emergency;